#include <cstdint>
#include <cstring>

// Assuming Rect is defined with the following members:
// int x, y, width, height
// and the pixel buffer is accessed via a global or known context.

struct Rect {
    int x;
    int y;
    int width;
    int height;
};

// Assuming the pixel buffer is represented as a global variable or known context
// For example:
// uint8_t* pixelBuffer;
// int bufferWidth;
// int bufferHeight;
// int bytesPerPixel;

void fillRect(const Rect& r, const void* pix) {
    // Check for empty rectangle
    if (r.width <= 0 || r.height <= 0) {
        return;
    }

    // Validate rectangle is within buffer bounds
    if (r.x < 0 || r.y < 0 || r.x + r.width > bufferWidth || r.y + r.height > bufferHeight) {
        return;
    }

    // Calculate the bytes per pixel
    int bytesPerPixel = 1; // Default to 1 byte per pixel

    // Determine the bytes per pixel based on the pixel data size
    // For example, if the pixel data is 3 bytes (RGB), set bytesPerPixel = 3
    // This is a placeholder and should be replaced with actual logic to determine bytesPerPixel

    // Calculate the starting index in the pixel buffer
    int startIndex = (r.y * bufferWidth + r.x) * bytesPerPixel;

    // Calculate the number of bytes to fill
    int bytesToFill = r.width * r.height * bytesPerPixel;

    // Check for overflow in bytesToFill calculation
    if (r.width > 0 && r.height > 0 && bytesToFill / r.width != r.height * bytesPerPixel) {
        return; // Overflow detected
    }

    // Check if the pixel data is valid
    if (!pix) {
        return; // Invalid pixel data
    }

    // Fill the pixel buffer
    if (bytesPerPixel == 1) {
        // Single byte per pixel
        uint8_t pixelValue = *static_cast<const uint8_t*>(pix);
        std::memset(pixelBuffer + startIndex, pixelValue, bytesToFill);
    } else {
        // Multiple bytes per pixel
        std::memcpy(pixelBuffer + startIndex, pix, bytesToFill);
    }
}
